// Writes b8-load.scm, chapter 03 Appendix B's eighth benchmark: about 200 KB
// of definitions, the size of an scm/ module, evaluated once, so it times
// reading and compiling more than running. The definitions are the
// appendix's; the first line says what it prints, as b1–b7's do, and a
// second names this script.
//
//   node tools/bench/gen-b8.mjs > tools/bench/b8-load.scm
//
// crates/scheme/tests/bench.rs checks that the file is this script's output.
const out = [
  ';;; b8-load.scm, prints 416',
  ';; generated by gen-b8.mjs: definitions the size of an scm/ module, read and evaluated once',
]
for (let i = 0; i < 700; i++) {
  out.push(`(define (f${i} x y) (if (< x y) (cons x (list y 'sym${i} "string ${i}")) (let ((z (+ x y ${i}))) (cond ((> z 100) (* z 2)) ((= z 0) 'zero) (else (list z x y))))))`)
  out.push(`(define data${i} '((name . grob${i}) (stencil . ${i}) (X-extent ${i} . ${i + 1}) (meta (class . Item) (interfaces grob-interface item-interface))))`)
}
out.push(`(define (check i acc) (if (= i 700) acc (check (+ i 1) (+ acc (cdr (assq 'stencil (eval (string->symbol (string-append "data" (number->string i))) (interaction-environment))))))))`)
out.push('(display (+ (length (f3 1 2)) (f5 200 1))) (newline)')
process.stdout.write(out.join('\n') + '\n')
